from review import card,save,DATE
i='TCS-6251';_,c=card(i);refs=c['references'];refs[0]['locator']='Introduction, pages 93:2–93:3: polynomial-time conjecture for every forbidden forest whose components have at most three leaves.'
refs += [dict(id='quasipoly',title='Maximum Weight Independent Set in Graphs with no Long Claws in Quasi-Polynomial Time',authors='Peter Gartland; Daniel Lokshtanov; Tomáš Masařík; Marcin Pilipczuk; Michał Pilipczuk; Paweł Rzążewski',year=2024,url='https://doi.org/10.1145/3618260.3649791',pdf_url='https://arxiv.org/pdf/2305.15738v4',locator='STOC 2024; full version 4, 23 September 2025, Conjecture 1.1, Theorems 1.3–1.4 and the nonnegative-integer weight convention.'),dict(id='improved',title="Graphs with No Long Claws: An Improved Bound for the Analog of the Gyárfás’ Path Argument",authors='Romain Bourneuf; Jana Masaříková; Wojciech Nadara; Marcin Pilipczuk',year=2025,url='https://doi.org/10.4230/LIPIcs.MFCS.2025.28',locator='Abstract and Section 1: improved quasipolynomial bounds and polynomial algorithms under additional sparsity restrictions; the general polynomial conjecture remains.')]
save(i,dict(title='Polynomial-time independent set under a forbidden forest',
formal=r'For every fixed finite forest \(H\) whose connected components each have at most three leaves, does Maximum Weight Independent Set on \(H\)-free graphs admit a deterministic polynomial-time algorithm? Precisely, must there exist an algorithm \(A_{H}\) and constants \(c_{H},C_{H}>0\) that, for every \(H\)-free vertex-weighted graph \((G,w)\) of encoding length \(L\), output a maximum-weight independent set in at most \(C_{H}(L+1)^{c_{H}}\) steps?',
definitions=r'''Graphs are finite, undirected and simple. A forest has no cycle. In a nontrivial tree, a leaf has degree one; an isolated vertex is allowed as a component. A tree with at most three leaves is a path or a subdivided claw. A subdivided claw \(S_{a,b,c}\), for integers \(a,b,c\geq1\), consists of three internally disjoint paths of respectively \(a,b,c\) edges sharing one endpoint. That common endpoint has degree three, and the other endpoints are the three leaves.

The graph \(G\) is \(H\)-free if no vertex subset induces a graph isomorphic to \(H\). An induced copy must preserve both edges and nonedges. If \(H\) is disconnected, all its components must occur together with no extra edges between their chosen vertices. Excluding the whole forest is therefore not the same as separately excluding every component.

The input explicitly lists \(G\) and nonnegative integer vertex weights \(w(v)\), encoded in binary. The length \(L\) includes the graph and all weight bits; zero weights and the empty independent set are allowed. An independent set \(I\subseteq V(G)\) contains no pair joined by an edge. Its weight is
\[w(I)=\sum_{v\in I}w(v).\]
The required output is a set \(I\) attaining the largest possible weight, not merely an inclusion-maximal set or an approximation.

The forbidden graph \(H\) is fixed before the input varies. The algorithm, polynomial exponent and multiplicative constant may depend on \(H\). The question does not require one exponent independent of \(H\), or fixed-parameter tractability when \(H\) is treated as a variable input. It asks for ordinary polynomial bit complexity for each fixed class.

There is no bound on the maximum degree, clique size or biclique size of \(G\). No sparsity promise is imposed beyond the forbidden induced forest. Recognition of \(H\)-freeness can be done in polynomial time for fixed \(H\), but the optimization guarantee is required only on that class.

Computing the exact optimum value and outputting an optimum set are polynomial-time equivalent here by the usual self-reduction on induced subgraphs, which remain \(H\)-free. The primary source discusses the full family of forests; the symmetric long claws \(S_{t,t,t}\) are a central subfamily, not an unmentioned restriction of this formulation.''',
question_type='yes_no',answer_criterion='Prove polynomial-time solvability for every fixed forest in the stated family, or refute this assertion for at least one fixed forest. Any complexity assumption used for a negative result must be explicit. A quasipolynomial-time algorithm, an approximation scheme or a theorem requiring bounded degree or a forbidden biclique does not meet the full target.',
context_blocks=[
dict(title='This is the remaining side of a structural classification',text='The sources recall that forbidding a fixed graph outside this forest family leaves Maximum Weight Independent Set NP-hard. Polynomial algorithms for every forest in the family would identify the tractable side of the classification for a single forbidden induced subgraph.',citation='quasipoly'),
dict(title='The entire family now has quasipolynomial algorithms',text=r'Theorem 1.3 of the September 2025 full version gives an algorithm for every such fixed \(H\), with graph-size running time \(n^{O_{H}((\log n)^{19})}\). This is major progress over the earlier subexponential and approximation results, but its exponent still grows with \(n\). Conjecture 1.1 in that same version retains the polynomial target.',citation='quasipoly'),
dict(title='Sparse cases are already polynomial',text=r'The consolidated STACS 2024 source proves polynomial-time solvability when \(G\) excludes both an induced \(S_{t,t,t}\) and a fixed complete bipartite graph \(K_{s,s}\) as an ordinary subgraph. Its Conjecture 10 asks about replacing the biclique restriction by a clique restriction. Both restrictions are additional to the general question on this card.',citation='consolidated_2103_primary'),
dict(title='Later structural improvement preserves the gap',text='The 2025 MFCS paper improves the structural theorem behind the quasipolynomial algorithms and simplifies polynomial algorithms in sparse cases. It still describes polynomial-time solvability for the full family as conjectural. A manuscript title on an author’s publications page omits “bounded-degree”; the linked paper itself retains that restriction.',citation='improved')],
why='This conjecture would complete a natural complexity classification of a central optimization problem by forbidden induced structure. It asks whether the large family now admitting quasipolynomial algorithms actually permits polynomial-time exact optimization, including graphs of unrestricted density.',
progress=[dict(date='2022',text='The source advances subexponential and approximation algorithms while retaining the full polynomial-time conjecture.',citation='primary'),dict(date='2024',text='A quasipolynomial-time algorithm covers every forbidden forest in the conjectured tractable family.',citation='quasipoly'),dict(date='2025',text='A stronger structural theorem improves quasipolynomial bounds; the revised full algorithm paper retains Conjecture 1.1.',citation='improved')],
references=refs,status='open',status_note='Read the original full-family paragraph, the consolidated 2024 sparse theorem and Conjecture 10, the September 2025 full quasipolynomial version, and the 2025 MFCS introduction. Checked the apparently broader polynomial manuscript on the author’s site: the linked PDF is explicitly bounded-degree. Searches through 12 September 2026 found no polynomial algorithm for the complete family.',
model_self_contained=True,requires_context=False,review_note='Recovered the universal fixed-forbidden-forest conjecture, induced containment, weighted optimum and per-class polynomial quantifiers. Preserved the consolidated sparse source while separating its extra assumptions. Removed algorithm-design suggestions.',
importance=dict(score=c['importance']['score'],method='editorial',reason='A major remaining tractability boundary for Maximum Weight Independent Set on hereditary classes, now with quasipolynomial algorithms across the conjectured polynomial side. Existing score retained.',assessed_on=DATE),
working_summary=dict(sentences=['Fix a forest whose components are paths or subdivided three-leaf claws.','Given a graph with no induced copy of that forest, find an independent vertex set of maximum total weight.','The question asks for polynomial time for every fixed forbidden forest, with the polynomial allowed to depend on that forest.','The input graph may have arbitrarily large degree, cliques and bicliques.','Quasipolynomial algorithms now cover the whole family, but known general results still fall short of polynomial time.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','quasipoly','improved'])),
notes=['Restored every fixed forbidden forest with components having at most three leaves.','Defined induced containment, disconnected forests, integer weights and exact optimization.','Made fixed-class polynomial quantifiers explicit without requiring a universal exponent.','Updated the quasipolynomial result and distinguished sparse polynomial special cases.'],checked_sources=[r['url'] for r in refs]+['https://web.math.princeton.edu/~mchudnov/longclaws.pdf'])
